import{_ as t,o as n,c as r,ag as a}from"./chunks/framework.W-j76G-U.js";const p=JSON.parse('{"title":"Lab 2 : automatiser une tâche récurrente","description":"","frontmatter":{},"headers":[],"relativePath":"handout-03-lab-2-tache-recurrente.md","filePath":"handout-03-lab-2-tache-recurrente.md","handout":{"fichier":"handout-03-lab-2-tache-recurrente.md","markdown":"# Handout — Lab 2 : automatiser une tâche récurrente\\n\\n**Bootcamp AI-Driven Development · Module 0 · Zenika · support d\'exercice**\\n\\nLab optionnel (~25 min) : transformer une tâche faite « à la main » chaque semaine en un Project ou une Skill réutilisable en 30 secondes.\\n\\n## Étapes\\n\\n1. **Choisir une tâche récurrente** : CR de réunion, relance client, brief offre, réponse candidat…\\n2. **Créer un Project / une Skill** dédié, avec un nom clair.\\n3. **Rédiger les instructions** : destinataire, ton, format de sortie, quoi éviter.\\n4. **Ajouter 2-3 exemples** en pièces jointes, ce qui fait passer de « correct » à « on dirait vous ».\\n5. **Tester sur un cas réel** et affiner selon ce qui manque ou dérape.\\n\\n> **Règle d\'or** : pas de données client confidentielles sans validation DSI, données anonymisées ou cas internes.\\n\\n## Project ou Skill ?\\n\\n|            | Project                                          | Skill                                                       |\\n| ---------- | ------------------------------------------------ | ----------------------------------------------------------- |\\n| Porte      | un **contexte**                                  | une **compétence** reproductible                            |\\n| Exemple    | « tout sur le client X »                         | « comment rédiger un CR chez nous »                         |\\n| Contenu    | documents de référence, instructions, historique | un `SKILL.md` (mode d\'emploi) + des fichiers de support     |\\n| Chargement | quand on travaille dans le Project               | **automatiquement**, quand la Skill correspond à la demande |\\n| Partage    | au sein d\'une Team Anthropic                     | au sein d\'une Team Anthropic, comme un Project              |\\n\\nLes deux se combinent.\\n\\n## Structure minimale d\'une Skill\\n\\n- un **nom** + une **description** (quand l\'activer) ;\\n- un `SKILL.md` (étapes, règles, pièges) ;\\n- en option des templates / checklists.\\n\\nPour la créer : demandez à Claude « je veux créer une nouvelle skill », ou passez par le menu **Customize**.\\n\\n```text\\nJe veux créer une nouvelle skill.\\n```\\n"}}'),o={name:"handout-03-lab-2-tache-recurrente.md"};function i(s,e,u,l,d,c){return n(),r("div",null,[...e[0]||(e[0]=[a('<p class="zh-type">support d’exercice</p><h1 id="handout-lab-2-automatiser-une-tache-recurrente" tabindex="-1">Lab 2 : automatiser une tâche récurrente <a class="header-anchor" href="#handout-lab-2-automatiser-une-tache-recurrente" aria-label="Permalink to &quot;Handout — Lab 2 : automatiser une tâche récurrente&quot;">​</a></h1><p>Lab optionnel (~25 min) : transformer une tâche faite « à la main » chaque semaine en un Project ou une Skill réutilisable en 30 secondes.</p><h2 id="etapes" tabindex="-1">Étapes <a class="header-anchor" href="#etapes" aria-label="Permalink to &quot;Étapes&quot;">​</a></h2><ol><li><strong>Choisir une tâche récurrente</strong> : CR de réunion, relance client, brief offre, réponse candidat…</li><li><strong>Créer un Project / une Skill</strong> dédié, avec un nom clair.</li><li><strong>Rédiger les instructions</strong> : destinataire, ton, format de sortie, quoi éviter.</li><li><strong>Ajouter 2-3 exemples</strong> en pièces jointes, ce qui fait passer de « correct » à « on dirait vous ».</li><li><strong>Tester sur un cas réel</strong> et affiner selon ce qui manque ou dérape.</li></ol><blockquote><p><strong>Règle d’or</strong> : pas de données client confidentielles sans validation DSI, données anonymisées ou cas internes.</p></blockquote><h2 id="project-ou-skill" tabindex="-1">Project ou Skill ? <a class="header-anchor" href="#project-ou-skill" aria-label="Permalink to &quot;Project ou Skill ?&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Project</th><th>Skill</th></tr></thead><tbody><tr><td>Porte</td><td>un <strong>contexte</strong></td><td>une <strong>compétence</strong> reproductible</td></tr><tr><td>Exemple</td><td>« tout sur le client X »</td><td>« comment rédiger un CR chez nous »</td></tr><tr><td>Contenu</td><td>documents de référence, instructions, historique</td><td>un <code>SKILL.md</code> (mode d’emploi) + des fichiers de support</td></tr><tr><td>Chargement</td><td>quand on travaille dans le Project</td><td><strong>automatiquement</strong>, quand la Skill correspond à la demande</td></tr><tr><td>Partage</td><td>au sein d’une Team Anthropic</td><td>au sein d’une Team Anthropic, comme un Project</td></tr></tbody></table><p>Les deux se combinent.</p><h2 id="structure-minimale-d-une-skill" tabindex="-1">Structure minimale d’une Skill <a class="header-anchor" href="#structure-minimale-d-une-skill" aria-label="Permalink to &quot;Structure minimale d&#39;une Skill&quot;">​</a></h2><ul><li>un <strong>nom</strong> + une <strong>description</strong> (quand l’activer) ;</li><li>un <code>SKILL.md</code> (étapes, règles, pièges) ;</li><li>en option des templates / checklists.</li></ul><p>Pour la créer : demandez à Claude « je veux créer une nouvelle skill », ou passez par le menu <strong>Customize</strong>.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Je veux créer une nouvelle skill.</span></span></code></pre></div>',13)])])}const h=t(o,[["render",i]]);export{p as __pageData,h as default};
